-- SOLO LECTURA. Contrato de aprobacion: cada consulta devuelve una fila control/errores, todos en cero.
SELECT 'destino' AS control, (CASE WHEN DATABASE() REGEXP '^c3c1_lab_[a-f0-9]{32}$' THEN 0 ELSE 1 END) AS errores;
SELECT 'tablas_innodb' AS control, (2 - (SELECT COUNT(*) FROM information_schema.TABLES WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME IN ('cont_ejercicios','cont_periodos') AND ENGINE='InnoDB')) AS errores;
SELECT 'columnas' AS control, ((SELECT COUNT(*) FROM (SELECT 'cont_ejercicios' AS tabla, 'id' AS columna, 'int' AS tipo UNION ALL SELECT 'cont_ejercicios' AS tabla, 'empresa_id' AS columna, 'int' AS tipo UNION ALL SELECT 'cont_ejercicios' AS tabla, 'entidad_id' AS columna, 'int' AS tipo UNION ALL SELECT 'cont_ejercicios' AS tabla, 'codigo' AS columna, 'varchar' AS tipo UNION ALL SELECT 'cont_ejercicios' AS tabla, 'fecha_inicio' AS columna, 'date' AS tipo UNION ALL SELECT 'cont_ejercicios' AS tabla, 'fecha_fin' AS columna, 'date' AS tipo UNION ALL SELECT 'cont_ejercicios' AS tabla, 'estado' AS columna, 'varchar' AS tipo UNION ALL SELECT 'cont_ejercicios' AS tabla, 'creado_por' AS columna, 'int' AS tipo UNION ALL SELECT 'cont_ejercicios' AS tabla, 'creado_en' AS columna, 'datetime' AS tipo UNION ALL SELECT 'cont_periodos' AS tabla, 'id' AS columna, 'int' AS tipo UNION ALL SELECT 'cont_periodos' AS tabla, 'empresa_id' AS columna, 'int' AS tipo UNION ALL SELECT 'cont_periodos' AS tabla, 'entidad_id' AS columna, 'int' AS tipo UNION ALL SELECT 'cont_periodos' AS tabla, 'ejercicio_id' AS columna, 'int' AS tipo UNION ALL SELECT 'cont_periodos' AS tabla, 'orden' AS columna, 'smallint' AS tipo UNION ALL SELECT 'cont_periodos' AS tabla, 'codigo' AS columna, 'varchar' AS tipo UNION ALL SELECT 'cont_periodos' AS tabla, 'fecha_inicio' AS columna, 'date' AS tipo UNION ALL SELECT 'cont_periodos' AS tabla, 'fecha_fin' AS columna, 'date' AS tipo UNION ALL SELECT 'cont_periodos' AS tabla, 'estado' AS columna, 'varchar' AS tipo UNION ALL SELECT 'cont_periodos' AS tabla, 'creado_por' AS columna, 'int' AS tipo UNION ALL SELECT 'cont_periodos' AS tabla, 'creado_en' AS columna, 'datetime' AS tipo) e LEFT JOIN information_schema.COLUMNS c ON c.TABLE_SCHEMA=DATABASE() AND c.TABLE_NAME=e.tabla AND c.COLUMN_NAME=e.columna WHERE c.COLUMN_NAME IS NULL OR c.DATA_TYPE<>e.tipo OR c.IS_NULLABLE<>'NO' OR (e.tipo='int' AND c.COLUMN_TYPE LIKE '%unsigned%') OR (e.columna='orden' AND c.COLUMN_TYPE NOT LIKE '%unsigned%') OR (e.columna='codigo' AND (c.CHARACTER_MAXIMUM_LENGTH<>40 OR c.COLLATION_NAME<>'ascii_bin')) OR (e.columna='estado' AND (c.CHARACTER_MAXIMUM_LENGTH<>20 OR REPLACE(COALESCE(c.COLUMN_DEFAULT,''),CHAR(39),'')<>'CONFIGURADO')) OR (e.columna='id' AND c.EXTRA NOT LIKE '%auto_increment%'))) AS errores;
SELECT 'numero_columnas' AS control, (ABS(20 - (SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME IN ('cont_ejercicios','cont_periodos')))) AS errores;
SELECT 'indices_unicos' AS control, (5 - (SELECT COUNT(*) FROM (SELECT TABLE_NAME,INDEX_NAME,GROUP_CONCAT(COLUMN_NAME ORDER BY SEQ_IN_INDEX) AS cols FROM information_schema.STATISTICS WHERE TABLE_SCHEMA=DATABASE() AND NON_UNIQUE=0 AND TABLE_NAME IN ('cont_ejercicios','cont_periodos') GROUP BY TABLE_NAME,INDEX_NAME) x WHERE (TABLE_NAME='cont_ejercicios' AND INDEX_NAME='uq_ce_codigo' AND cols='empresa_id,entidad_id,codigo') OR (TABLE_NAME='cont_ejercicios' AND INDEX_NAME='uq_ce_ambito' AND cols='empresa_id,entidad_id,id') OR (TABLE_NAME='cont_periodos' AND INDEX_NAME='uq_cp_codigo' AND cols='empresa_id,entidad_id,ejercicio_id,codigo') OR (TABLE_NAME='cont_periodos' AND INDEX_NAME='uq_cp_orden' AND cols='empresa_id,entidad_id,ejercicio_id,orden') OR (TABLE_NAME='cont_periodos' AND INDEX_NAME='uq_cp_ambito' AND cols='empresa_id,entidad_id,id'))) AS errores;
SELECT 'fk_compuestas_y_acciones' AS control, (4 - (SELECT COUNT(*) FROM (SELECT k.TABLE_NAME,k.CONSTRAINT_NAME,k.REFERENCED_TABLE_NAME,GROUP_CONCAT(k.COLUMN_NAME ORDER BY k.ORDINAL_POSITION) AS cols,GROUP_CONCAT(k.REFERENCED_COLUMN_NAME ORDER BY k.ORDINAL_POSITION) AS destino FROM information_schema.KEY_COLUMN_USAGE k WHERE k.TABLE_SCHEMA=DATABASE() AND k.REFERENCED_TABLE_SCHEMA=DATABASE() AND k.TABLE_NAME IN ('cont_ejercicios','cont_periodos') AND k.REFERENCED_TABLE_NAME IS NOT NULL GROUP BY k.TABLE_NAME,k.CONSTRAINT_NAME,k.REFERENCED_TABLE_NAME) x JOIN information_schema.REFERENTIAL_CONSTRAINTS r ON r.CONSTRAINT_SCHEMA=DATABASE() AND r.TABLE_NAME=x.TABLE_NAME AND r.CONSTRAINT_NAME=x.CONSTRAINT_NAME WHERE r.UPDATE_RULE='RESTRICT' AND r.DELETE_RULE='RESTRICT' AND ((x.CONSTRAINT_NAME='fk_ce_entidad' AND x.TABLE_NAME='cont_ejercicios' AND x.REFERENCED_TABLE_NAME='cont_entidades' AND x.cols='empresa_id,entidad_id' AND x.destino='empresa_id,id') OR (x.CONSTRAINT_NAME='fk_ce_actor' AND x.TABLE_NAME='cont_ejercicios' AND x.REFERENCED_TABLE_NAME='usuarios' AND x.cols='creado_por' AND x.destino='id') OR (x.CONSTRAINT_NAME='fk_cp_ejercicio' AND x.TABLE_NAME='cont_periodos' AND x.REFERENCED_TABLE_NAME='cont_ejercicios' AND x.cols='empresa_id,entidad_id,ejercicio_id' AND x.destino='empresa_id,entidad_id,id') OR (x.CONSTRAINT_NAME='fk_cp_actor' AND x.TABLE_NAME='cont_periodos' AND x.REFERENCED_TABLE_NAME='usuarios' AND x.cols='creado_por' AND x.destino='id')))) AS errores;
SELECT 'checks_declarados' AS control, (7 - (SELECT COUNT(*) FROM information_schema.TABLE_CONSTRAINTS t JOIN information_schema.CHECK_CONSTRAINTS c ON c.CONSTRAINT_SCHEMA=t.CONSTRAINT_SCHEMA AND c.CONSTRAINT_NAME=t.CONSTRAINT_NAME WHERE t.CONSTRAINT_SCHEMA=DATABASE() AND t.CONSTRAINT_TYPE='CHECK' AND ((t.TABLE_NAME='cont_ejercicios' AND t.CONSTRAINT_NAME IN ('ck_ce_fechas','ck_ce_estado','ck_ce_codigo')) OR (t.TABLE_NAME='cont_periodos' AND t.CONSTRAINT_NAME IN ('ck_cp_fechas','ck_cp_estado','ck_cp_codigo','ck_cp_orden'))) AND LENGTH(c.CHECK_CLAUSE)>0)) AS errores;
SELECT 'ejercicios_solapados' AS control, ((SELECT COUNT(*) FROM cont_ejercicios a JOIN cont_ejercicios b ON a.empresa_id=b.empresa_id AND a.entidad_id=b.entidad_id AND a.id<b.id AND a.fecha_inicio<=b.fecha_fin AND a.fecha_fin>=b.fecha_inicio)) AS errores;
SELECT 'cobertura' AS control, ((SELECT COUNT(*) FROM cont_ejercicios e LEFT JOIN (SELECT empresa_id,entidad_id,ejercicio_id,COUNT(*) AS n,MIN(orden) AS primero,MAX(orden) AS ultimo,MIN(fecha_inicio) AS inicio,MAX(fecha_fin) AS fin FROM cont_periodos GROUP BY empresa_id,entidad_id,ejercicio_id) p ON p.empresa_id=e.empresa_id AND p.entidad_id=e.entidad_id AND p.ejercicio_id=e.id WHERE p.n IS NULL OR p.n>366 OR p.primero<>1 OR p.ultimo<>p.n OR p.inicio<>e.fecha_inicio OR p.fin<>e.fecha_fin)) AS errores;
SELECT 'periodos_validos' AS control, ((SELECT COUNT(*) FROM cont_periodos p LEFT JOIN cont_ejercicios e ON e.empresa_id=p.empresa_id AND e.entidad_id=p.entidad_id AND e.id=p.ejercicio_id WHERE e.id IS NULL OR p.fecha_inicio<e.fecha_inicio OR p.fecha_fin>e.fecha_fin OR p.fecha_inicio>p.fecha_fin OR p.estado<>'CONFIGURADO')) AS errores;
SELECT 'consecutivos' AS control, ((SELECT COUNT(*) FROM cont_periodos p JOIN cont_periodos q ON p.empresa_id=q.empresa_id AND p.entidad_id=q.entidad_id AND p.ejercicio_id=q.ejercicio_id AND q.orden=p.orden+1 WHERE q.fecha_inicio<>DATE_ADD(p.fecha_fin,INTERVAL 1 DAY))) AS errores;
SELECT 'estado_ejercicios' AS control, ((SELECT COUNT(*) FROM cont_ejercicios WHERE estado<>'CONFIGURADO')) AS errores;
